"""Module which handles Telemetry Resource."""

import platform
from uuid import uuid1

import opentelemetry.sdk.resources as resources

session_code = uuid1()


class HostResourceDetector(resources.ResourceDetector):
    """Resource detector class to get basic information about Telemetry source."""

    def detect(self) -> resources.Resource:
        """Collect resource information and return Resource object."""
        _host_name = platform.node()
        # _host_type = ""
        # _host_arch = platform.machine()
        resource_info = {
            resources.HOST_NAME: _host_name,
            "taf.ul.telemetry.version": "0.1.13",
            # resources.HOST_TYPE: _host_type,
            # "host.arch": _host_arch,
            resources.SERVICE_INSTANCE_ID: str(session_code),
        }
        return resources.Resource(resource_info)
